  function editPost(card,post){const body=q('.cc9-post-body',card);if(!body||q('.cc9-post-edit',card))return;const editor=document.createElement('div');editor.className='cc9-post-edit';editor.innerHTML=`<textarea maxlength="1200">${esc(post.body||'')}</textarea><div class="cc9-post-edit-actions"><button class="btn dark" type="button" data-cancel>Cancelar</button><button class="btn gold" type="button" data-save>Salvar</button></div>`;body.after(editor);body.hidden=true;q('[data-cancel]',editor).addEventListener('click',()=>{editor.remove();body.hidden=false;});q('[data-save]',editor).addEventListener('click',async e=>{const text=q('textarea',editor).value.trim();e.currentTarget.disabled=true;const {error}=await db.from('cosplay_social_posts').update({body:text||null,updated_at:new Date().toISOString()}).eq('id',post.id);if(error){e.currentTarget.disabled=false;toast('Não foi possível editar.','error');return;}post.body=text;body.innerHTML=linkify(text);editor.remove();body.hidden=false;});}

  async function toggleComments(card,post){let root=q('.cc9-comments',card);if(root){root.remove();return;}root=document.createElement('div');root.className='cc9-comments';root.innerHTML='<div class="cc9-empty">Carregando comentários...</div>';card.appendChild(root);const {data,error}=await db.from('cosplay_social_comments').select('id,post_id,author_profile_id,parent_comment_id,body,created_at,updated_at').eq('post_id',post.id).eq('moderation_status','active').order('created_at',{ascending:true}).limit(200);if(error){root.innerHTML='<div class="cc9-empty">Não foi possível carregar os comentários.</div>';return;}const rows=data||[];await loadProfiles(rows.map(x=>x.author_profile_id));renderComments(root,post,rows);}
  function renderComments(root,post,rows){const me=state.profile;root.replaceChildren();const list=document.createElement('div');list.className='cc9-comments-list';const renderRow=(c,reply=false)=>{const p=state.profiles.get(c.author_profile_id);const el=document.createElement('div');el.className=`cc9-comment${reply?' reply':''}`;const img=safeUrl(p?.character_photo_url);el.innerHTML=`<span class="cc9-comment-avatar">${img?`<img src="${esc(img)}" alt="">`:'♜'}</span><div class="cc9-comment-bubble"><b>${esc(displayName(p))}</b><p>${linkify(c.body)}</p><div class="cc9-comment-meta"><span>${esc(relative(c.created_at))}</span><button type="button" data-reply>Responder</button>${c.author_profile_id===me?.id?'<button type="button" data-edit>Editar</button><button type="button" data-delete>Excluir</button>':''}</div></div>`;q('[data-reply]',el).addEventListener('click',()=>{form.dataset.parent=c.id;note.textContent=`Respondendo a ${displayName(p)} · clique para cancelar`;input.focus();});q('[data-delete]',el)?.addEventListener('click',async()=>{if(!confirm('Excluir comentário?'))return;await db.from('cosplay_social_comments').delete().eq('id',c.id);toggleComments(root.closest('.cc9-post'),post);setTimeout(()=>q('[data-comment]',root.closest('.cc9-post'))?.click(),50);});q('[data-edit]',el)?.addEventListener('click',async()=>{const next=prompt('Editar comentário:',c.body);if(next==null||!next.trim())return;const {error}=await db.from('cosplay_social_comments').update({body:next.trim(),updated_at:new Date().toISOString()}).eq('id',c.id);if(!error){c.body=next.trim();q('p',el).innerHTML=linkify(c.body);}});return el;};
    const parents=rows.filter(x=>!x.parent_comment_id);parents.forEach(c=>{list.appendChild(renderRow(c));rows.filter(x=>x.parent_comment_id===c.id).forEach(r=>list.appendChild(renderRow(r,true)));});if(!rows.length)list.innerHTML='<div class="cc9-empty">Nenhum comentário ainda.</div>';root.appendChild(list);
    const note=document.createElement('div');note.className='cc9-comment-reply-note';note.addEventListener('click',()=>{form.dataset.parent='';note.textContent='';});const form=document.createElement('form');form.className='cc9-comment-form';const input=document.createElement('input');input.maxLength=1200;input.required=true;input.placeholder='Escreva um comentário...';const send=document.createElement('button');send.type='submit';send.textContent='Comentar';form.append(input,send);root.append(note,form);form.addEventListener('submit',async e=>{e.preventDefault();const body=input.value.trim();if(!body||!me)return;send.disabled=true;const payload={post_id:post.id,author_profile_id:me.id,body};if(form.dataset.parent)payload.parent_comment_id=form.dataset.parent;const {error}=await db.from('cosplay_social_comments').insert(payload);send.disabled=false;if(error){toast('Não foi possível comentar.','error');return;}input.value='';form.dataset.parent='';note.textContent='';toggleComments(root.closest('.cc9-post'),post);setTimeout(()=>q('[data-comment]',root.closest('.cc9-post'))?.click(),60);});}

  function openHashtag(tag){state.hashtag=String(tag||'').replace(/^#/,'').toLowerCase();state.feedMode='recent';qa('.cc-feed-tabs button').forEach(b=>b.classList.toggle('active',b.dataset.feedMode==='recent'));switchPanel('feed',q('.community-nav [data-community-view="feed"]'));$('ccGlobalSearch').value='#'+state.hashtag;ensureSearchPopover().hidden=true;loadFeed(true);}

