  async function routeNotification(type,id,actor){if(type==='profile'||(!type&&actor)){const p=state.profiles.get(actor)||state.profiles.get(id);if(p?.public_slug)location.href=profileHref(p);return;}if(type==='post'&&id){switchPanel('feed',q('.community-nav [data-community-view="feed"]'));await focusPost(id);return;}if(type==='community'&&id){const {data}=await db.from('cosplay_communities').select('slug').eq('id',id).maybeSingle();if(data?.slug)location.href=`./comunidade-grupo.html?slug=${encodeURIComponent(data.slug)}`;}}
  async function focusPost(id){const {data,error}=await db.from('cosplay_social_posts').select('id,author_profile_id,body,image_path,video_path,visibility,post_type,metadata,created_at,updated_at').eq('id',id).maybeSingle();if(error||!data){toast('A publicação não está mais disponível.');return;}await loadProfiles([data.author_profile_id]);const p=state.profiles.get(data.author_profile_id);const [{count:likes},{count:comments},{count:shares},{data:saved},{data:liked}]=await Promise.all([db.from('cosplay_social_post_likes').select('*',{count:'exact',head:true}).eq('post_id',id),db.from('cosplay_social_comments').select('*',{count:'exact',head:true}).eq('post_id',id).eq('moderation_status','active'),db.from('cosplay_social_post_shares').select('*',{count:'exact',head:true}).eq('post_id',id),db.from('cosplay_saved_posts').select('post_id').eq('profile_id',state.profile.id).eq('post_id',id).maybeSingle(),db.from('cosplay_social_post_likes').select('post_id').eq('profile_id',state.profile.id).eq('post_id',id).maybeSingle()]);const row={...data,...p,like_count:likes||0,comment_count:comments||0,share_count:shares||0,saved_by_me:!!saved,liked_by_me:!!liked};const extras=await batchExtras([row]);const feed=$('communityFeed');feed.replaceChildren(await renderPost(row,extras));setTimeout(()=>feed.scrollIntoView({behavior:'smooth',block:'start'}),20);}

