  async function sendMessage(e,peerId){e.preventDefault();const form=e.currentTarget,me=state.profile,body=form.elements.body.value.trim(),file=$('cc9MessageImage')?.files?.[0];if(!body&&!file)return;const btn=form.querySelector('button');btn.disabled=true;let path=null;try{if(file){if(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>8*1024*1024)throw new Error('Use JPG, PNG ou WebP com até 8 MB.');const ext=file.type==='image/png'?'png':file.type==='image/webp'?'webp':'jpg';path=`${state.user.id}/${me.id}/messages/${Date.now()}-${Math.random().toString(36).slice(2,8)}.${ext}`;const up=await db.storage.from(BUCKET).upload(path,file,{contentType:file.type,upsert:false});if(up.error)throw up.error;}const {error}=await db.from('cosplay_direct_messages').insert({sender_profile_id:me.id,recipient_profile_id:peerId,body:body||'',attachment_path:path,attachment_type:path?'image':'text'});if(error)throw error;form.reset();await renderMessages();state.selectedPeer=peerId;renderThreads();renderConversation();}catch(err){if(path)await db.storage.from(BUCKET).remove([path]).catch(()=>{});toast(err?.message||'Não foi possível enviar a mensagem.','error');}finally{btn.disabled=false;}}
  function setupTyping(peerId){try{state.typingChannel?.unsubscribe();}catch{}const ids=[state.profile.id,peerId].sort().join(':');const ch=db.channel(`cc-dm-typing-${ids}`,{config:{broadcast:{self:false}}});ch.on('broadcast',{event:'typing'},payload=>{if(payload.payload?.from===peerId){const el=$('cc9Typing');if(el){el.textContent=`${displayName(state.profiles.get(peerId))} está digitando...`;clearTimeout(el._t);el._t=setTimeout(()=>el.textContent='',1300);}}});ch.subscribe();state.typingChannel=ch;}
