  async function renderRanking(period='all'){const panel=ensurePanel('ranking');panel.innerHTML=`<div class="cc9-panel"><div class="cc9-panel-head"><div><h2>Ranking social</h2><p>XP calculado por participação real, sem premiar spam.</p></div><div class="cc9-panel-toolbar"><button class="cc9-chip ${period==='week'?'active':''}" data-period="week">7 dias</button><button class="cc9-chip ${period==='month'?'active':''}" data-period="month">30 dias</button><button class="cc9-chip ${period==='all'?'active':''}" data-period="all">Geral</button></div></div><div id="cc9Ranking" class="cc9-ranking-list"><div class="cc9-empty">Carregando ranking...</div></div></div>`;qa('[data-period]',panel).forEach(b=>b.addEventListener('click',()=>renderRanking(b.dataset.period)));const {data,error}=await db.rpc('cosplay_social_ranking_period',{p_period:period,p_limit:50});if(error){$('cc9Ranking').innerHTML='<div class="cc9-empty">Não foi possível carregar o ranking.</div>';return;}$('cc9Ranking').innerHTML=(data||[]).map((r,i)=>{const img=safeUrl(r.character_photo_url);return `<article class="cc9-ranking-row"><b class="cc9-rank-pos">${i+1}</b>${img?`<img src="${esc(img)}" alt="">`:'<span class="cc9-result-avatar">♜</span>'}<div><a href="./jogador.html?slug=${encodeURIComponent(r.public_slug||'')}">${esc(r.display_name)}</a><span>${esc(r.character_name||'CosplayChess')}</span></div><div class="cc9-rank-score"><b>${r.score} XP</b><small>Nível ${r.level}</small></div></article>`;}).join('')||'<div class="cc9-empty">Sem dados suficientes ainda.</div>';}

